const SEED_STUDENT_COUNT=12;
const defaultMeasures={reading:'5-question reading check',math:'5-item problem-solving check',writing:'5-opportunity writing sample'};
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function goalPlansFor(id){return state.goalPlans?.[id]||[]}
function activeGoal(id){const plans=goalPlansFor(id);return plans.find(g=>g.id===activeGoalIds[id])||plans[0]||null}
function approvedObjectives(g){return (g?.objectives||[]).filter(o=>o.status==='approved')}
function activeObjective(id){const g=activeGoal(id),list=approvedObjectives(g);return list.find(o=>o.id===activeObjectiveIds[id])||list[list.length-1]||null}
function findGoal(id,gid){return goalPlansFor(id).find(g=>g.id===gid)}
function objectiveLogs(id,oid){return state.logs.filter(l=>l.student===id&&l.objective===oid)}
function scoreForObjective(s,o){if(!o)return null;return objectiveLogs(s.id,o.id)[0]?.score??(o.sample?s.score:null)}
function smartText(o,s){return `By ${formatDate(o.deadline)}, ${new Date(o.deadline+'T12:00:00').getFullYear()}, ${s.name.split(' ')[0]} will ${o.skill.replace(/[.!?]$/,'').replace(/^./,c=>c.toLowerCase())}, ${o.condition.replace(/[.!?]$/,'')}, with at least ${o.target}% accuracy across ${o.checks} consecutive checks.`}
function draftObjectives(s,g,seed=false){const total=Math.max(21,Math.round((new Date(g.deadline+'T12:00:00')-new Date(TODAY+'T12:00:00'))/86400000));const known=g.title.toLowerCase()===goalSummaries[g.domain].toLowerCase();const skills=known?{
 reading:['Identify the first and last events in a short story','Put two story events in order','Sequence three events in a short story'],
 math:['Choose addition or subtraction for a one-step problem','Solve one-step addition problems','Solve one-step addition and subtraction problems'],
 writing:['State a complete idea aloud before writing','Write a complete sentence using a sentence frame','Write a complete sentence with a clear idea']
}[g.domain]:[g.title,g.title,g.title];return skills.map((skill,i)=>({id:seed?g.id+'-o'+(i+1):uid('objective'),skill,condition:i===0?'with a worked example and usual accommodations':i===1?'with a visual guide and usual accommodations':'with usual accommodations',target:80,checks:3,deadline:i===2?g.deadline:datePlus(Math.round(total*(i+1)/3)),status:seed?'approved':'draft',sample:seed&&i===2}));}
function initializeModel(){state.assignments ||= [];state.addedStudents ||= [];for(const s of state.addedStudents)if(!students.some(x=>x.id===s.id))students.push(s);if(!state.goalPlans){state.goalPlans={};for(const s of students){if(s.isNew){state.goalPlans[s.id]=[];continue}const p=state.plans[s.id]||initialPlans()[s.id];const g={id:'goal-'+s.id,domain:s.domain,title:p.goal,deadline:p.deadline,measurement:{method:p.method,frequency:p.frequency||'2',review:p.review}};g.objectives=draftObjectives(s,g,true);g.objectives[2].target=p.target||80;if(s.id==='samira')g.objectives[2].status='draft';state.goalPlans[s.id]=[g]}}for(const log of state.logs){if(!log.objective){const g=goalPlansFor(log.student)[0];if(g){log.goal=g.id;log.objective=g.objectives[g.objectives.length-1]?.id}}}state.schemaVersion=3;}
function addStudentModal(){openModal('Add student','',`<form id="student-form"><div class="field"><label for="student-name">Student name</label><input id="student-name" name="name" required maxlength="100" placeholder="First and last name" autocomplete="off"></div><div class="field"><label for="student-grade">Grade</label><select id="student-grade" name="grade">${Array.from({length:13},(_,i)=>`<option value="${i}" ${i===3?'selected':''}>${i===0?'Kindergarten':'Grade '+i}</option>`).join('')}</select></div><div id="student-error"></div><div class="modal-foot">${btn('Cancel','close')}<button class="btn primary" type="submit">Add student</button></div></form>`)}
function goalModal(id,gid=''){const g=findGoal(id,gid);openModal(g?'Edit goal':'Set an IEP goal',getStudent(id).name,`<form id="goal-form"><input type="hidden" name="student" value="${id}"><input type="hidden" name="goalId" value="${gid}"><div class="field"><label for="goal-domain">Goal area</label><select id="goal-domain" name="domain">${Object.entries(domainNames).map(([v,l])=>`<option value="${v}" ${(g?.domain||getStudent(id).domain)===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="goal-title">What should the student be able to do?</label><textarea id="goal-title" name="title" required maxlength="1000" placeholder="e.g. Sequence three events in a short story">${esc(g?.title||'')}</textarea></div><div class="field"><label for="goal-deadline">Goal date</label><input id="goal-deadline" type="date" name="deadline" min="${datePlus(21)}" value="${g?.deadline||'2027-05-21'}" required></div><div id="goal-error"></div><div class="modal-foot"><span class="caption">${g?'Changes require another objective review.':'Review and edit the generated SMART objectives.'}</span><button class="btn primary" type="submit">${g?'Save goal':'Generate objectives'}</button></div></form>`)}
function objectiveModal(id,gid,oid=''){const g=findGoal(id,gid),o=g?.objectives.find(o=>o.id===oid);if(!g)return;openModal(o?'Edit objective':'Add objective',g.title,`<form id="objective-form"><input type="hidden" name="student" value="${id}"><input type="hidden" name="goalId" value="${gid}"><input type="hidden" name="objectiveId" value="${oid}"><div class="field"><label for="objective-skill">Specific skill</label><textarea id="objective-skill" name="skill" required maxlength="1200" placeholder="e.g. Put two story events in order">${esc(o?.skill||'')}</textarea></div><div class="field-row"><div class="field"><label for="objective-target">Accuracy target (%)</label><input id="objective-target" name="target" type="number" min="1" max="100" value="${o?.target||80}" required></div><div class="field"><label for="objective-deadline">By date</label><input id="objective-deadline" name="deadline" type="date" min="${TODAY}" max="${g.deadline}" value="${o?.deadline||g.deadline}" required></div></div><details class="disclosure"><summary>Support and measurement</summary><div class="field"><label for="objective-condition">Support conditions</label><input id="objective-condition" name="condition" value="${esc(o?.condition||'with usual accommodations')}" required maxlength="500"></div><div class="field"><label for="objective-checks">Consecutive successful checks</label><input id="objective-checks" name="checks" type="number" min="1" max="10" value="${o?.checks||3}" required></div></details><div id="objective-error"></div><div class="modal-foot"><span class="caption">Teacher approval follows this edit.</span><button class="btn primary" type="submit">${o?'Save objective':'Draft SMART objective'}</button></div></form>`)}
function measurementModal(id,gid){const g=findGoal(id,gid);if(!g)return;const m=g.measurement;openModal('Measurement plan',g.title,`<form id="measurement-form"><input type="hidden" name="student" value="${id}"><input type="hidden" name="goalId" value="${gid}"><div class="field"><label for="measure-method">What will you collect?</label><input id="measure-method" name="method" value="${esc(m.method)}" required maxlength="500"></div><div class="field-row"><div class="field"><label for="measure-frequency">How often?</label><select id="measure-frequency" name="frequency">${[1,2,3,4,5].map(n=>`<option value="${n}" ${+m.frequency===n?'selected':''}>${n} ${n===1?'time':'times'} per week</option>`).join('')}</select></div><div class="field"><label for="measure-review">Review date</label><input id="measure-review" name="review" type="date" min="${TODAY}" max="${g.deadline}" value="${m.review}" required></div></div><div id="measurement-error"></div><div class="modal-foot">${btn('Cancel','close')}<button class="btn primary" type="submit">Save measurement plan</button></div></form>`)}
function lessonGoalsFor(id,domain){return goalPlansFor(id).filter(g=>g.domain===domain&&approvedObjectives(g).length)}
function lessonObjectiveOptions(id,domain){return lessonGoalsFor(id,domain).flatMap(g=>approvedObjectives(g).map(o=>({...o,goalId:g.id,goalTitle:g.title})))}
function defaultLessonObjective(id,domain){const list=lessonObjectiveOptions(id,domain);return list[list.length-1]||null}
function preserveLessonInputs(){preserveDraftInputs(lesson,document.getElementById('lesson-form'))}
function weekStart(iso){const d=new Date(iso+'T12:00:00Z'),day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day);return d.toISOString().slice(0,10)}
function weekLabel(iso){const end=new Date(iso+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+6);return formatDate(iso)+' – '+formatDate(end.toISOString().slice(0,10))}
function notesFor(s){const custom=state.contexts.filter(c=>c.student===s.id).map(c=>({...c,dateISO:c.dateISO||TODAY}));const sample=s.isNew?[]:sampleContexts(s).map((c,i)=>({...c,id:'sample-note-'+s.id+'-'+i,dateISO:['2026-10-08','2026-10-07','2026-10-06'][i]||'2026-10-06'}));if(!s.isNew)sample.push({id:'sample-prior-'+s.id,role:'General education teacher',author:'Jordan Bell',initials:'JB',color:'blue',dateISO:'2026-09-30',text:s.domain==='reading'?'Lost place when several directions appeared together. Oral retelling was easier than completing the written sequence.':s.domain==='math'?'Needed an adult cue to choose the first step, then completed the calculation.':'Shared a clear idea aloud. Needed an adult cue to start writing.'});return [...custom,...sample].sort((a,b)=>b.dateISO.localeCompare(a.dateISO));}
function notesDigest(s){const notes=notesFor(s),latest=new Map();for(const n of notes)if(!latest.has(n.role))latest.set(n.role,n);return [...latest.values()].map(n=>{const first=n.text.match(/^.*?[.!?](?:\s|$)/)?.[0]?.trim()||n.text;return {role:n.role,text:first.length>160?first.slice(0,157)+'…':first,note:n}})}
function guidanceFor(s){return guidanceRecommendations(s,notesFor(s))}

function initialPlans(){return Object.fromEntries(students.map(s=>[s.id,{
 goal:goalSummaries[s.domain],objective:goalSummaries[s.domain],objectiveTarget:60,objectiveDeadline:'2026-12-18',condition:s.domain==='reading'?'Given a grade-appropriate passage and the student’s usual accommodations':s.domain==='math'?'Given a one-step problem and the student’s usual accommodations':'Given a familiar topic and the student’s usual accommodations',baseline:40,target:80,probes:3,deadline:'2027-05-21',method:s.domain==='reading'?'5-question story sequencing probe':s.domain==='math'?'5-item problem-solving probe':'5-opportunity sentence-writing sample',frequency:s.id==='samira'?'':'2',owner:'Ms. Rivera',review:s.id==='ava'?'2026-10-16':s.id==='lucas'?'2026-10-19':'2026-11-06',report:'2026-10-30'
}]))}
function initialState(){return {plans:initialPlans(),logs:[],contexts:[],drafts:[],assignments:[],comparisons:[],lesson:null}}
let state;
try{state=JSON.parse(localStorage.getItem(STORE_KEY))||initialState();if(!state.plans||!state.logs||!state.contexts||!state.comparisons)state=initialState()}catch{state=initialState()}
initializeModel();
let activeGoalIds={},activeObjectiveIds={},notesSource='all';
let activeFilter='all',searchText='',studentTab='overview',studioTab='draft',studioStep=1,lesson=state.lesson||null,groups={a:[],b:[]},cohort=[],support='independent',lastFocus=null,toastTimer;
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));return true}catch{toast('Changes work for this visit; browser storage is unavailable.');return false}}
function getStudent(id){return students.find(s=>s.id===id)||students[0]}
function planFor(id){const g=activeGoal(id),o=activeObjective(id);return {goal:g?.title||'',target:o?.target||80,probes:o?.checks||3,deadline:g?.deadline||'',method:g?.measurement.method||'',frequency:g?.measurement.frequency||'',review:g?.measurement.review||''}}
function logsFor(id){return state.logs.filter(l=>l.student===id)}
function latestScore(s){return scoreForObjective(s,activeObjective(s.id))}
function avatar(s,size=''){return `<span class="avatar av-${s.color} ${size}" aria-hidden="true">${esc(s.initials)}</span>`}
function statusOf(s){if(!goalPlansFor(s.id).length)return 'setup';if(!activeObjective(s.id))return 'draft';if(latestScore(s)===null)return goalPlansFor(s.id).some(g=>g.objectives.some(o=>o.status!=='approved'))?'draft':'evidence';return s.status==='evidence'&&logsFor(s.id).length?'review':s.status}
function badgeFor(s){const type=statusOf(s);return `<span class="badge ${type==='track'?'green':type==='support'?'amber':type==='review'?'purple':'gray'}">${type==='track'?'On track':type==='support'?'Needs support':type==='review'?'Review new evidence':type==='setup'?'Set IEP goal':type==='draft'?'Review objectives':'Needs evidence'}</span>`}
function formatDate(value){if(!value)return 'Not set';const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?'Not set':d.toLocaleDateString('en-US',{month:'short',day:'numeric'})}
function datePlus(days){const d=new Date(TODAY+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function btn(label,action,type='',extra=''){return `<button class="btn ${type}" data-action="${action}" ${extra}>${label}</button>`}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function route(){const parts=(location.hash.slice(1)||'class').split('/');return {page:parts[0],id:parts[1]}}
function navigate(hash){closeModal();if(location.hash===`#${hash}`)render();else location.hash=hash}
function shell(content,page){const nav=page==='student'?'class':['comparison','assignments'].includes(page)?'studio':page;return `
 <aside class="sidebar"><a href="#class" class="brand" aria-label="Clearpath home">${logo}Clearpath</a><div class="workspace-name">Teacher workspace</div><nav class="nav" aria-label="Main navigation">
 <a href="#class" class="${nav==='class'?'active':''}" ${nav==='class'?'aria-current="page"':''}>${icon('class')}<span>My class</span><span class="nav-count">${students.length}</span></a>
 <a href="#plans" class="${nav==='plans'?'active':''}" ${nav==='plans'?'aria-current="page"':''}>${icon('plan')}<span>IEP plans</span></a>
 <a href="#studio" class="${nav==='studio'?'active':''}" ${nav==='studio'?'aria-current="page"':''}>${icon('book')}<span>Generate assignments</span></a></nav>
 <div class="sidebar-bottom"><div class="demo-note"><button data-action="about">${icon('info')}About this prototype</button></div><div class="profile"><div class="profile-avatar">MR</div><div><strong>Ms. Rivera</strong><small>Grade 3 teacher</small></div></div></div></aside>
 <div class="shell"><header class="topbar"><div class="breadcrumb">Maple Elementary <span>/</span><strong>Room 204</strong></div><a class="mobile-brand" href="#class">${logo}Clearpath</a><div class="topbar-right"><span class="date">Friday, October 9</span><span class="sample-pill"><i></i>Demo · Sample data</span></div></header><main id="main" tabindex="-1">${content}</main></div>`}
function render(){const r=route();let content;if(r.page==='student')content=studentView(getStudent(r.id));else if(r.page==='plans')content=plansView();else if(r.page==='studio')content=studioView();else if(r.page==='comparison')content=comparisonView(r.id);else if(r.page==='assignments')content=assignmentOverview(r.id);else content=classView();app.innerHTML=shell(content,r.page);document.title=`Clearpath · ${r.page==='student'?getStudent(r.id).name:r.page==='plans'?'IEP plans':r.page==='studio'?'Generate assignments':r.page==='comparison'?'Teaching plan':r.page==='assignments'?'Assignment overview':'My class'}`}

function classView(){const missing=students.filter(s=>statusOf(s)==='evidence').length,support=students.filter(s=>statusOf(s)==='support').length;return `<div class="page-head"><div><h1>My class</h1><p class="subtitle">${students.length} students</p></div><div class="actions">${btn('Generate assignment','new-lesson')}${btn(icon('plus')+'Add student','add-student','primary')}</div></div><section aria-label="Students"><div class="table-card"><div class="toolbar"><div class="filter-tabs" aria-label="Filter students">${[['all','All students',students.length],['support','Needs support',support],['evidence','Needs evidence',missing],['guidance','New inputs',students.filter(s=>hasNewGuidance(s.id)).length]].map(([v,l,n])=>`<button class="filter ${activeFilter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${activeFilter===v}">${l}<span>${n}</span></button>`).join('')}</div><label class="search">${icon('search')}<span class="sr-only">Search students</span><input id="student-search" type="search" placeholder="Search students" value="${esc(searchText)}" autocomplete="off"></label></div><div class="table-wrap"><table class="roster"><thead><tr><th>Student</th><th class="focus-cell">Goal area</th><th>Progress</th><th class="status-cell">Status</th><th class="evidence-col">Last recorded</th><th></th></tr></thead><tbody id="roster-body">${rosterRows()}</tbody></table></div><div class="table-foot"><span id="roster-count">${filteredStudents().length} of ${students.length} students</span><span>Current objective accuracy / target</span></div></div></section>`}

function filteredStudents(){return alphabeticalStudents(students.filter(s=>(activeFilter==='all'||(activeFilter==='guidance'?hasNewGuidance(s.id):statusOf(s)===activeFilter))&&s.name.toLowerCase().includes(searchText.toLowerCase())))}
function rosterRows(){return filteredStudents().map(s=>{const g=activeGoal(s.id),score=latestScore(s);return `<tr><td><a class="student-name" href="#student/${s.id}">${avatar(s)}<span><span class="name-text">${esc(s.name)}</span><small>${s.grade===0?'Kindergarten':'Grade '+s.grade}${hasNewGuidance(s.id)?' · '+guidanceInputLabel(s):''}</small></span></a></td><td class="focus-cell">${g?domainNames[g.domain]:'—'}</td><td class="progress-cell">${score===null?'<span class="muted">No records</span>':`<div class="progress-numbers"><strong>${score}%</strong><span>/ ${planFor(s.id).target}% target</span></div><div class="progress-track"><i style="width:${Math.min(score/planFor(s.id).target*100,100)}%"></i></div>`}</td><td class="status-cell">${badgeFor(s)}</td><td class="evidence-col">${logsFor(s.id).length?'Just recorded':s.last}</td><td>${hasNewGuidance(s.id)?`<button class="text-btn row-view guidance-row-action" data-action="review-guidance" data-id="${s.id}"><i class="unread-dot"></i>${guidanceChanged(guidanceUpdate(s.id))?'New guidance':'New input'} ${icon('chevron')}</button>`:`<a href="#student/${s.id}" class="text-btn row-view" aria-label="View ${esc(s.name)}">View ${icon('chevron')}</a>`}</td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">No students found.</div></td></tr>'}

function progressChart(s){const o=activeObjective(s.id),recorded=objectiveLogs(s.id,o?.id).slice().reverse().map(l=>l.score);const values=[...(o?.sample?s.points:[]),...recorded].slice(-8);if(!values.length)return '<p class="empty-records">No progress recorded for this objective.</p>';const w=490,h=190,left=31,right=18,top=15,bottom=32;const x=i=>left+i*(w-left-right)/Math.max(1,values.length-1);const y=v=>top+(100-v)*(h-top-bottom)/100;const path=values.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');const target=planFor(s.id).target;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(s.name)} progress: ${values.join(', ')} percent. Target: ${target} percent.">${[0,40,80].map(v=>`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#edf1e7"/><text x="0" y="${y(v)+4}">${v}%</text>`).join('')}<line x1="${left}" y1="${y(target)}" x2="${w-right}" y2="${y(target)}" stroke="#b8c9ab" stroke-dasharray="4 4"/><text x="${w-right-53}" y="${y(target)-8}" class="target-label">Goal ${target}%</text><path d="${path}" fill="none" stroke="#7a9a67" stroke-width="2.5" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#7a9a67" stroke-width="2"><title>Probe ${i+1}: ${v}%</title></circle>`).join('')}<text x="${left}" y="${h-5}">Earlier probes</text><text x="${w-53}" y="${h-5}">Latest</text></svg><div class="chart-legend"><span><i class="legend-line"></i>Independent answers</span><span><i class="legend-line dashed"></i>IEP target</span></div>`}
function studentView(s){const gs=goalPlansFor(s.id),pending=gs.flatMap(g=>g.objectives).filter(o=>o.status!=='approved');let action='';if(studentTab==='plan')action=`<div class="actions">${btn(gs.length?'Add goal':'Set goal','add-goal',pending.length?'':'primary',`data-id="${s.id}"`)}${pending.length?btn('Approve objectives','approve-all','primary',`data-id="${s.id}"`):''}</div>`;else if(studentTab==='evidence')action=btn('Add note','context','',`data-id="${s.id}"`);else if(activeObjective(s.id))action=btn('Record progress','record-progress','primary',`data-id="${s.id}"`);return `<a href="#class" class="back">${icon('back')}My class</a><div class="page-head"><div class="student-heading">${avatar(s,'big')}<div><h1>${esc(s.name)}</h1><p class="subtitle">${s.grade===0?'Kindergarten':'Grade '+s.grade}</p></div></div>${action}</div><div class="tabs" role="tablist" aria-label="Student details">${[['overview','Progress'],['plan','IEP plan'],['evidence','Notes']].map(([v,l])=>`<button role="tab" aria-selected="${studentTab===v}" class="tab ${studentTab===v?'active':''}" data-action="student-tab" data-value="${v}">${l}${v==='evidence'&&hasNewGuidance(s.id)?`<span class="tab-unread"><i class="unread-dot"></i>${newGuidanceNotes(s).length} new</span>`:''}</button>`).join('')}</div><div role="tabpanel">${studentTab==='plan'?studentPlan(s):studentTab==='evidence'?studentEvidence(s):studentOverview(s)}</div>`}

function suggestionFor(s){return s.domain==='reading'?{title:'Show one direction at a time',body:'The therapist observed longer engagement with one-step directions.',sources:['Therapist · Oct 8','Teacher · Oct 7'],change:'Show one direction at a time. Keep the passage, questions, and usual accommodations.'}:s.domain==='math'?{title:'Separate the problem-solving steps',body:'The teacher noted difficulty choosing relevant information, despite correct verbal calculations.',sources:['Teacher · Oct 8'],change:'Place identify, solve, and check steps in separate visual boxes. Keep the same problems.'}:{title:'Add a visual word bank',body:'The student shares ideas aloud but pauses before writing.',sources:['Teacher · Oct 8','Parent · Oct 6'],change:'Add visual cues to the word bank. Keep the same writing task and usual accommodations.'}}

function sampleContexts(s){const first=s.name.split(' ')[0];return s.domain==='reading'?[
 {role:'Occupational therapist',author:'Maya Chen',initials:'MC',color:'lilac',date:'Oct 8',text:`${first} stayed with the task longer when the page showed one step at a time. Several directions together seemed harder to get started with.`},
 {role:'General education teacher',author:'Jordan Bell',initials:'JB',color:'blue',date:'Oct 7',text:`During story discussion, ${first} could explain the events aloud. Independent sequencing was harder when the worksheet was text only.`},
 {role:'Parent',author:'Family note',initials:'FN',color:'peach',date:'Oct 6',text:`At home, ${first} retold a familiar story using the pictures before looking at the words.`}
 ]:s.domain==='math'?[
 {role:'General education teacher',author:'Jordan Bell',initials:'JB',color:'blue',date:'Oct 8',text:`${first} explained the calculation aloud but needed help deciding which information in the story to use.`},
 {role:'Parent',author:'Family note',initials:'FN',color:'peach',date:'Oct 6',text:'A worked example helped with getting started on homework.'}
 ]:[
 {role:'General education teacher',author:'Jordan Bell',initials:'JB',color:'blue',date:'Oct 8',text:`${first} shared a clear idea aloud, then paused for several minutes before beginning to write.`},
 {role:'Parent',author:'Family note',initials:'FN',color:'peach',date:'Oct 6',text:'Talking through a sentence before writing seemed to make homework easier to start.'}
 ]}
function contextList(s){return notesFor(s).map(n=>noteEntry(n)).join('')}
function stakeholderProfile(n){
 const key=(n.author+'|'+n.role).toLowerCase(),hash=Array.from(key).reduce((h,c)=>(h*31+c.charCodeAt(0))>>>0,0);
 const presets=[{bg:'#e9eeeb',skin:'#d7a887',hair:'#44372f',shirt:'#73877b',style:0},{bg:'#eeeaf1',skin:'#e9bb99',hair:'#51473e',shirt:'#938ca1',style:1},{bg:'#f0ece5',skin:'#a97654',hair:'#302f2c',shirt:'#a28e74',style:2},{bg:'#e7ecef',skin:'#ebc7a5',hair:'#7e5c3d',shirt:'#778b9a',style:3},{bg:'#eeece7',skin:'#b37f5b',hair:'#393532',shirt:'#8a907a',style:1},{bg:'#eee9e7',skin:'#d3a081',hair:'#5d443b',shirt:'#ab8980',style:0}];
 const v=presets[hash%presets.length],hair=[`<path d="M13 25V18C13 7 35 6 35 19v10l-5-5V15c-4 4-8 5-13 5v7Z" fill="${v.hair}"/>`,`<path d="M12 30V19c0-15 24-15 24 0v13l-6-4V16c-7 5-10 5-13 4v10Z" fill="${v.hair}"/>`,`<path d="M13 20c-5-3-1-11 3-10 0-5 7-6 10-3 5-2 11 2 10 7 4 5 1 9-2 10l-4-9-13 1-1 7Z" fill="${v.hair}"/>`,`<path d="M13 23V16c0-10 23-12 23 2l-4 6-2-11c-5 5-9 3-14 6v7Z" fill="${v.hair}"/>`][v.style];
 return `<svg class="stakeholder-avatar" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="24" fill="${v.bg}"/><path d="M5 49c0-11 7-17 19-17s19 6 19 17Z" fill="${v.shirt}"/>${hair}<path d="M20 29h8v7c-2 3-6 3-8 0Z" fill="${v.skin}"/><ellipse cx="24" cy="22" rx="9" ry="11" fill="${v.skin}"/><path d="M15 20c0-7 3-11 9-11 7 0 10 5 10 10-4-1-6-5-6-7-3 5-8 7-13 8Z" fill="${v.hair}"/><path d="M19 23h1m8 0h1" stroke="#403833" stroke-width="1.7" stroke-linecap="round"/><path d="M22 28q2 2 4 0" stroke="#835345" fill="none" stroke-width="1.1" stroke-linecap="round"/><path d="m18 35 6 5 6-5" stroke="#ffffff80" stroke-width="1.5" fill="none"/></svg>`;
}
function noteCitation(n,index){const label=`Source ${index}: ${n.author}, ${n.role}, ${formatDate(n.dateISO)}. Open note.`;return `<a class="note-citation" href="#${n.id}" data-action="show-note" data-note="${n.id}" title="${esc(n.role+' · '+n.author+' · '+formatDate(n.dateISO))}" aria-label="${esc(label)}">[${index}]</a>`}
function notesSummary(s){
 const digest=notesDigest(s);
 return `<p class="notes-summary">${digest.map((d,i)=>`${esc(d.text)} ${noteCitation(d.note,i+1)}`).join(' ')}</p>`;
}
function noteEntry(n){return `<article class="note-entry" id="${n.id}" tabindex="-1"><div class="note-entry-head">${stakeholderProfile(n)}<div class="note-person"><strong>${esc(n.author)}</strong><span>${esc(n.role)}</span></div><time datetime="${n.dateISO}">${formatDate(n.dateISO)}</time></div><p>${esc(n.text)}</p></article>`}


function studentOverview(s){
 const gs=goalPlansFor(s.id),g=activeGoal(s.id),o=activeObjective(s.id);
 if(!g)return `<div class="content-column"><div class="empty-plan"><h2>No IEP goal yet</h2>${btn('Set an IEP goal','add-goal','primary',`data-id="${s.id}"`)}</div>${assignmentHistory(s)}</div>`;
 const approved=approvedObjectives(g);
 return `<div class="content-column"><div class="field-row progress-selectors"><div class="field"><label for="progress-goal">Goal</label><select id="progress-goal" data-student="${s.id}">${gs.map(x=>`<option value="${x.id}" ${g.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label for="progress-objective">Objective</label><select id="progress-objective" data-student="${s.id}" ${approved.length?'':'disabled'}>${approved.length?approved.map(x=>`<option value="${x.id}" ${o?.id===x.id?'selected':''}>Objective ${g.objectives.indexOf(x)+1} · ${esc(x.skill)}</option>`).join(''):'<option>Awaiting teacher approval</option>'}</select></div></div>${!o?`<div class="empty-plan"><h2>Review the objective drafts</h2>${btn('Review objectives','student-tab','primary','data-value="plan"')}</div>`:`<section class="content-section progress-section" aria-label="Objective progress"><p class="section-description">${o.target}% across ${o.checks} checks · Due ${formatDate(o.deadline)}</p>${latestScore(s)!==null?`<div class="metric-row"><strong class="metric">${latestScore(s)}%</strong><span class="muted">latest accuracy</span></div>`:''}${progressChart(s)}</section>`}${assignmentHistory(s)}</div>`;
}

function planChecks(p){return [['Goal',!!p.title],['Established objectives',p.objectives?.length>0&&p.objectives.every(o=>o.status==='approved')],['Measurement plan',!!(p.measurement?.method&&p.measurement.frequency&&p.measurement.review)]]}
function planComplete(p){return planChecks(p).every(([,ok])=>ok)}

function studentPlan(s){
 const gs=goalPlansFor(s.id);
 if(!gs.length)return '<div class="empty-plan"><h2>No IEP goals yet</h2><p>Set a goal to generate its SMART objectives.</p></div>';
 return `<div class="content-column iep-plan">${gs.map((g,i)=>{
  const drafts=g.objectives.filter(o=>o.status!=='approved').length;
  return `<section class="goal-block" aria-labelledby="plan-${g.id}">
   <div class="goal-heading"><div><div class="goal-label">Goal ${i+1} · ${domainNames[g.domain]}</div><h2 id="plan-${g.id}">${esc(g.title)}</h2><div class="goal-meta"><span>By ${formatDate(g.deadline)}, ${g.deadline.slice(0,4)}</span>${drafts?`<span>${drafts} ${drafts===1?'draft':'drafts'} to review</span>`:g.objectives.length?`<span class="established-plan">${icon('check')}Established</span>`:''}</div></div><button class="text-btn" data-action="edit-goal" data-id="${s.id}" data-goal="${g.id}">Edit goal</button></div>
   <div class="objectives-nested"><div class="section-row objectives-top"><span class="caption no-margin">${g.objectives.length} ${g.objectives.length===1?'objective':'objectives'}</span><button class="text-btn" data-action="add-objective" data-id="${s.id}" data-goal="${g.id}">+ Add objective</button></div>
    <ol class="objective-list" aria-label="Objectives for Goal ${i+1}">${g.objectives.map((o,j)=>`<li class="objective-item ${o.status==='approved'?'established':'is-draft'}"><div class="objective-heading"><h3>Objective ${j+1}${o.status!=='approved'?'<span class="draft-label">Draft</span>':''}</h3><button class="text-btn" data-action="edit-objective" data-id="${s.id}" data-goal="${g.id}" data-objective="${o.id}" aria-label="Edit objective ${j+1}">Edit</button></div><p>${esc(smartText(o,s))}</p>${o.status!=='approved'?`<button class="text-btn objective-approve" data-action="approve-objective" data-id="${s.id}" data-goal="${g.id}" data-objective="${o.id}">Approve objective</button>`:''}</li>`).join('')}
    </ol>
   </div><div class="measurement-section"><div class="section-row"><h3>Measurement plan</h3><button class="text-btn" data-action="edit-measurement" data-id="${s.id}" data-goal="${g.id}">Edit</button></div><dl class="measurement-list"><div><dt>Collect</dt><dd>${esc(g.measurement.method)}</dd></div><div><dt>Frequency</dt><dd>${g.measurement.frequency} ${+g.measurement.frequency===1?'time':'times'} per week</dd></div><div><dt>Review</dt><dd>${formatDate(g.measurement.review)}</dd></div></dl></div>
  </section>`;
 }).join('')}</div>`;
}

function studentEvidence(s){const notes=notesFor(s);if(!notes.length)return `<div class="empty-plan"><h2>No notes yet</h2><p>Add observations from teachers, therapists, or family.</p></div>`;const filtered=notes.filter(n=>notesSource==='all'||n.role===notesSource),weeks=[...new Set(filtered.map(n=>weekStart(n.dateISO)))];return `<div class="content-column">${guidanceSection(s)}<section class="content-section notes-overview"><div class="section-row"><h2>Summary</h2><span class="caption no-margin">${notes.length} notes · ${new Set(notes.map(n=>n.role)).size} sources</span></div>${notesSummary(s)}</section><section><div class="section-row"><h2>Notes by week</h2><label class="source-filter"><span class="sr-only">Filter notes by source</span><select id="notes-source"><option value="all">All sources</option>${[...new Set(notes.map(n=>n.role))].map(role=>`<option ${notesSource===role?'selected':''}>${esc(role)}</option>`).join('')}</select></label></div>${weeks.map((w,i)=>`<details class="week-group" ${i===0?'open':''}><summary>${weekLabel(w)} <span>${filtered.filter(n=>weekStart(n.dateISO)===w).length} notes</span></summary>${filtered.filter(n=>weekStart(n.dateISO)===w).map(noteEntry).join('')}</details>`).join('')}</section></div>`}


function plansView(){const pending=students.filter(s=>goalPlansFor(s.id).some(g=>!planComplete(g))).length;return `<div class="page-head"><div><h1>IEP plans</h1><p class="subtitle">${students.length} students${pending?' · '+pending+' plans need review':''}</p></div></div><div class="table-card"><div class="table-wrap"><table class="roster plan-table"><thead><tr><th>Student</th><th>Goals</th><th>Objectives</th><th>Plan status</th><th></th></tr></thead><tbody>${alphabeticalStudents().map(s=>{const gs=goalPlansFor(s.id),os=gs.flatMap(g=>g.objectives),ready=gs.length&&gs.every(planComplete);return `<tr><td><a class="student-name" href="#student/${s.id}" data-action="open-student-plan" data-id="${s.id}">${avatar(s)}<span class="name-text">${esc(s.name)}</span></a></td><td>${gs.length}</td><td>${os.length}${os.some(o=>o.status!=='approved')?' · '+os.filter(o=>o.status!=='approved').length+' draft':''}</td><td><span class="badge ${ready?'green':'amber'}">${!gs.length?'Set goal':ready?'Established':'Needs review'}</span></td><td><button class="text-btn" data-action="open-student-plan" data-id="${s.id}">View plan ${icon('chevron')}</button></td></tr>`}).join('')}</tbody></table></div></div>`}

const lessonDefaults={
 reading:{title:'The garden after the rain',source:'Maya planted a seed in a small pot. That afternoon, rain began to fall. She moved the pot inside and put it by a sunny window. A few days later, a tiny green leaf appeared.',directionsA:'Read the story.\n1. What did Maya do first?\n2. What happened after the rain began?\n3. What happened at the end?\nPut the three events in order.',directionsB:'Look at the three picture cues, then read the story.\n1. What did Maya do first?\n2. What happened after the rain began?\n3. What happened at the end?\nPut the three events in order.',cueLabels:['A seed is planted','The rain begins','A leaf appears'],cueIcons:['sprout','rain','sun'],a:'Numbered text steps',b:'Text + picture cues',change:'Picture cues for the sequence',measure:'Independent accuracy on a 5-question sequencing probe'},
 math:{title:'Seeds for the school garden',source:'Maya has 8 seeds. Her friend brings 5 more seeds. How many seeds do they have altogether? Next, they plant 6 of the seeds. How many seeds are left?',directionsA:'Read each problem.\n1. Write the numbers you need.\n2. Choose addition or subtraction.\n3. Solve and check your answer.',directionsB:'Use the three boxes to organize your thinking.\n1. Write the numbers you need.\n2. Choose addition or subtraction.\n3. Solve and check your answer.',cueLabels:['Find the numbers','Choose an operation','Solve and check'],cueIcons:['search','plus','check'],a:'Numbered text steps',b:'Steps in visual boxes',change:'Visual boxes around the same problem-solving steps',measure:'Independent accuracy on a 5-item problem-solving probe'},
 writing:{title:'A moment in the garden',source:'Think of something you noticed in a garden or park. Write one complete sentence about it. Include who or what you saw and what happened.',directionsA:'Use this word bank if helpful: flower, leaf, bird, grew, flew, green.\nSay your idea aloud. Then write one sentence.\nCheck for a capital letter and ending punctuation.',directionsB:'Use the picture word bank if helpful: flower, leaf, bird, grew, flew, green.\nSay your idea aloud. Then write one sentence.\nCheck for a capital letter and ending punctuation.',cueLabels:['Choose an idea','Say your sentence','Write and check'],cueIcons:['bulb','message','edit'],a:'Text word bank',b:'Visual word bank',change:'Visual cues alongside the same writing steps',measure:'Independent success across 5 sentence-writing opportunities'}
};
function newLesson(domain='reading',context='',studentIds=[]){lesson=createLessonDraft(domain,context,studentIds);studioTab='draft';studioStep=1;groups={a:[],b:[]};cohort=lesson.studentIds.slice()}
function stepper(){return `<div class="stepper" aria-label="Variation workflow">${['Students & goals','Lesson versions','Teaching plan'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${studioStep===i+1?'active':studioStep>i+1?'done':''}"><span class="number">${studioStep>i+1?'✓':i+1}</span>${s}</span>`).join('')}</div>`}
function studioView(){if(!lesson)newLesson();const count=state.drafts.length+assignmentBatches().length;return `<div class="page-head"><h1>Generate assignments</h1>${studioTab!=='draft'?btn('Create assignment','new-lesson','primary'):''}</div><div class="tabs" role="tablist" aria-label="Assignment views">${[['draft','Create'],['saved','Saved materials'],['comparisons','Teaching plans']].map(([v,l])=>`<button class="tab ${studioTab===v?'active':''}" role="tab" aria-selected="${studioTab===v}" data-action="studio-tab" data-value="${v}">${l}${v==='saved'&&count?' · '+count:''}</button>`).join('')}</div><div role="tabpanel">${studioTab==='comparisons'?comparisonList():studioTab==='saved'?savedMaterials():studioStep===1?lessonForm():stepper()+(studioStep===2?variationsView():setupComparison())}</div>`}
function lessonForm(){return assignmentSetupForm(lesson)}
function lessonObjectives(){return assignmentObjectives(lesson)}

function worksheet(which,full=false,model=lesson){const d=lessonDefaults[model.domain];return `<div class="worksheet"><div class="eyebrow">Grade ${model.grade} · ${domainNames[model.domain]} · ${which==='a'?'Original lesson':'Modified lesson'}</div><h3>${esc(model.title)}</h3><p class="worksheet-objective">Target: ${[...new Set((model.studentIds||[]).map(id=>lessonObjectiveOptions(id,model.domain).find(o=>o.id===model.objectiveIds?.[id])?.skill).filter(Boolean))].map(esc).join('; ')}</p><div class="print-only small">Name: ____________________ Date: ______________</div>${which==='b'&&model.change!=='Show one instruction at a time'?`<div class="picture-steps">${d.cueLabels.map((l,i)=>`<div class="picture-step">${icon(model.custom?'image':d.cueIcons[i])}${model.custom?(model.domain==='reading'?['Beginning','Middle','End']:model.domain==='math'?['Find','Solve','Check']:['Idea','Say','Write'])[i]:l}</div>`).join('')}</div>`:''}<div class="passage">${esc(model.source)}</div><div class="directions">${esc(model['directions'+which.toUpperCase()])}</div>${full?'<div class="answer-line"></div><div class="answer-line"></div><div class="answer-line"></div>':''}</div>`}
function variationsView(){return `<div class="section-row"><div><h2>Review lesson versions</h2><p>${esc(lessonDefaults[lesson.domain].measure)} · Usual accommodations stay in place.</p></div><button class="text-btn" data-action="studio-step" data-value="1">${icon('edit')}Change students or targets</button></div><div class="equal-col">${['a','b'].map(v=>`<section class="card variation"><div class="variation-head"><div class="variation-title"><span class="letter ${v}">${v.toUpperCase()}</span><div><h3>${esc(lesson[v])}</h3><small>${v==='a'?'Original lesson':'Modified lesson'}</small></div></div><button class="icon-btn" data-action="edit-variation" data-value="${v}" aria-label="Edit version ${v.toUpperCase()}">${icon('edit')}</button></div>${worksheet(v)}<div class="worksheet-foot"><button class="text-btn" data-action="preview-worksheet" data-value="${v}">Preview assignment ${icon('arrow')}</button></div></section>`).join('')}</div><div class="comparison-notes"><div class="note"><strong>WHAT STAYS THE SAME</strong>Goal, content, scoring, and usual accommodations.</div><div class="note"><strong>WHAT CHANGES</strong>${esc(lesson.change)}.</div></div><div class="form-foot"><p>Review each assignment before use.</p><div class="actions">${btn(icon('save')+'Save draft','save-draft')}${btn('Set teaching schedule '+icon('arrow'),'studio-step','primary','data-value="3"')}</div></div>`}
function eligibleStudents(){return eligibleForDraft(lesson)}

function setupComparison(){return teachingPlanSetup()}

function groupPanels(){return groups.a.length||groups.b.length?`<div class="equal-col">${['a','b'].map(v=>`<div class="group-box"><div class="group-head"><div><div class="eyebrow">${v==='a'?'Original lesson':'Modified lesson'}</div><h4>${esc(lesson[v])}</h4><small>${groups[v].length} students</small></div></div>${alphabeticalIds(groups[v]).map(id=>{const s=getStudent(id);return `<div class="group-person">${avatar(s,'tiny')}<span>${esc(s.name)}</span><button class="icon-btn" data-action="move-group" data-id="${s.id}" data-value="${v}" aria-label="Assign ${esc(s.name)} to the ${v==='a'?'modified':'original'} lesson" title="Move to other group">${icon('swap')}</button></div>`}).join('')||'<p class="small muted">No students yet.</p>'}</div>`).join('')}</div>`:'<div class="comparison-empty">Assign students to see who uses the original and modified lessons.</div>'}
function shuffleStudents(ids,random=Math.random){const shuffled=ids.slice();for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}const split=Math.ceil(shuffled.length/2);return {a:shuffled.slice(0,split),b:shuffled.slice(split)}}
function comparisonList(){return `<div class="section-row"><div><h2>Teaching plans</h2></div></div><div class="comparison-list">${state.comparisons.map(c=>`<article class="card comparison-card"><div class="comparison-icon">${icon('compare')}</div><div class="comparison-body"><span class="badge gray">${trialPhaseLabel(c)}</span><h3 style="margin-top:9px">${esc(c.title)}</h3><p>Grade ${c.lesson.grade} · ${c.groups.a.length+c.groups.b.length} students · Review ${formatDate(c.review)}</p></div><a class="btn" href="#comparison/${c.id}">Open plan ${icon('arrow')}</a></article>`).join('')}<article class="card comparison-card"><div class="comparison-icon">${icon('compare')}</div><div class="comparison-body"><span class="badge green">Ready to review</span><h3 style="margin-top:9px">Picture cues vs. numbered text steps</h3><p>Grade 3 reading · 6 students · Sep 25 – Oct 9 · Sample comparison</p></div><a class="btn" href="#comparison/sample">Explore results ${icon('arrow')}</a></article></div>`}
function savedDrafts(){return savedMaterials()}

const sampleResults=[{id:'ava',group:'A',before:40,after:55},{id:'milo',group:'A',before:40,after:60},{id:'jayden',group:'A',before:40,after:55},{id:'lena',group:'B',before:40,after:70},{id:'noah',group:'B',before:40,after:75},{id:'zoe',group:'B',before:50,after:75}];
function sampleResultView(){return `<a href="#studio" class="back" data-action="back-comparisons">${icon('back')}Teaching plans</a><div class="page-head"><div><h1>Picture cues vs. text steps</h1><p class="subtitle">Grade 3 reading · 6 students · Sep 25 – Oct 9</p></div>${btn('Create next assignment','suggest-lesson','primary','data-id="ava"')}</div><div class="content-column"><section class="content-section"><h2>Results</h2><p class="section-description">Picture cues showed greater improvement in independent answers.</p><div class="results-graph"><div class="bar-row"><label>A · Text steps</label><div class="bar-bg"><div class="bar-fill" style="width:57%"></div></div><b>57%</b></div><div class="bar-row"><label>B · Picture cues</label><div class="bar-bg"><div class="bar-fill strong" style="width:73%"></div></div><b>73%</b></div></div><div class="result-metrics"><div class="result-metric"><strong>+17 pts</strong><small>A · from 40% to 57%</small></div><div class="result-metric"><strong>+30 pts</strong><small>B · from 43% to 73%</small></div></div><p class="caption">3 students per group · 6 probes each · Small sample; causes are unconfirmed.</p></section><section class="content-section"><h2>Student results</h2><table class="compact-table"><thead><tr><th>Student</th><th>Version</th><th>Baseline</th><th>Final</th><th>Change</th></tr></thead><tbody>${sampleResults.slice().sort((a,b)=>getStudent(a.id).name.localeCompare(getStudent(b.id).name)).map(r=>`<tr><td><a class="name-text" href="#student/${r.id}">${getStudent(r.id).name}</a></td><td>${r.group}</td><td>${r.before}%</td><td>${r.after}%</td><td>+${r.after-r.before} pts</td></tr>`).join('')}</tbody></table></section><section class="content-section"><h2>Next instructional change</h2><p class="section-description">Try picture cues with Group A. Keep the passage difficulty and questions comparable.</p><details class="disclosure"><summary>Possible explanation and supporting notes</summary><p>Visual cues may help students follow a sequence. Teacher and parent notes describe stronger oral retelling with pictures; the therapist noted longer engagement with one-step directions.</p><a class="text-btn" href="#student/ava" data-action="open-student-notes" data-id="ava">View notes ${icon('arrow')}</a><p class="caption">These observations suggest explanations, not measured causes.</p></details></section></div>`}

function comparisonView(id){return trialView(id)}

function openModal(title,subtitle,body,options={}){if(!overlay.innerHTML)lastFocus=document.activeElement;app.inert=true;overlay.innerHTML=`<div class="modal-backdrop ${options.drawer?'drawer-backdrop':''} ${options.printable?'printable':''}"><section class="modal ${options.drawer?'drawer':''} ${options.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title" tabindex="-1">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>overlay.querySelector('#modal-title')?.focus(),30)}
function closeModal(){if(!overlay.innerHTML||progressCapture?.saving)return;pendingGuidanceReview=null;if(!finishAssignmentModal())return;clearProgressCapture();overlay.innerHTML='';document.body.style.overflow='';app.inert=false;lastFocus?.focus?.()}

function editPlan(id){studentTab='plan';navigate('student/'+id)}

function contextModal(id){const s=getStudent(id);openModal('Add note',s.name,`<form id="context-form"><input type="hidden" name="student" value="${id}"><div class="field-row"><div class="field"><label for="context-role">Source</label><select name="role" id="context-role"><option>General education teacher</option><option>Special education teacher</option><option>Occupational therapist</option><option>Speech therapist</option><option>Parent</option><option>Paraprofessional</option></select></div><div class="field"><label for="context-author">Name</label><input name="author" id="context-author" required placeholder="e.g. Maya Chen" maxlength="100"></div></div><div class="field"><label for="context-date">Date</label><input id="context-date" name="dateISO" type="date" value="${TODAY}" required></div><div class="field"><label for="context-note">Observation</label><textarea name="text" id="context-note" required rows="5" maxlength="3000" placeholder="Include what the student was doing, what helped, and what made it harder."></textarea></div><div class="modal-foot">${btn('Cancel','close')}<button class="btn primary" type="submit">Save note</button></div></form>`)}
function about(){openModal('A calmer way to see what helps','An interactive Clearpath prototype, shaped around your six jobs to be done.',`<div class="help-grid">${[['Start with your class','Add students, select an objective, and record progress.'],['Make the plan measurable','Set a goal, review generated SMART objectives, and choose how to measure progress.'],['Create assignments','Draft and edit materials for selected students. Add variations when you want to compare approaches.']].map(([t,p],i)=>`<div class="help-item"><span class="number">${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div><div class="info-strip">${icon('info')}<span>All students, notes, and results are fictional. AI drafting and automatic guidance use demo rules. Changes are saved in this browser; there are no live school or stakeholder connections.</span></div><div class="modal-foot"><button class="text-btn" data-action="reset-confirm">Reset demo changes</button>${btn('Explore my class '+icon('arrow'),'close','primary')}</div>`)}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,value=el.dataset.value,gid=el.dataset.goal,oid=el.dataset.objective;e.preventDefault();
 if(a==='close')return closeModal();
 if(a==='about')return about();
 if(a==='add-student')return addStudentModal();
 if(a==='add-goal')return goalModal(id);
 if(a==='edit-goal')return goalModal(id,gid);
 if(a==='add-objective'||a==='edit-objective')return objectiveModal(id,gid,oid||'');
 if(a==='edit-measurement')return measurementModal(id,gid);
 if(a==='approve-objective'){const o=findGoal(id,gid)?.objectives.find(x=>x.id===oid);if(o){o.status='approved';o.approvedAt=TODAY;persist();render();toast('Objective added to the plan.')}return}
 if(a==='approve-all'){for(const g of goalPlansFor(id))for(const o of g.objectives){o.status='approved';o.approvedAt=TODAY}persist();render();toast('Objectives established.');return}
 if(a==='record-progress')return openProgressModal(id||'ava',el.dataset.comparison||'');
 if(handleProgressAction(a,el))return;
 if(handleGuidanceAction(a,el))return;
 if(handleTrialAction(a,el))return;
 if(handleAssignmentAction(a,el))return;
 if(a==='open-student-notes'){studentTab='evidence';return navigate('student/'+id)}
 if(a==='filter'){activeFilter=value;return render()}
 if(a==='student-tab'){studentTab=value;return render()}
 if(a==='edit-plan'||a==='open-student-plan'){studentTab='plan';return navigate('student/'+id)}
 if(a==='context')return contextModal(id);
 if(a==='new-lesson'){newLesson();return navigate('studio')}
 if(a==='suggest-lesson'){const s=getStudent(id),g=activeGoal(id),o=activeObjective(id);newLesson(g?.domain||s.domain,suggestionFor(s).change,[id]);if(o)lesson.objectiveIds[id]=o.id;return navigate('studio')}
 if(a==='show-note'){closeModal();studentTab='evidence';notesSource='all';render();const note=document.getElementById(el.dataset.note);if(note){const group=note.closest?.('details');if(group)group.open=true;note.classList.add('note-highlight');note.focus?.({preventScroll:true});note.scrollIntoView?.({behavior:'smooth',block:'center'});}return}
 if(a==='select-all-students'){preserveLessonInputs();lesson.studentIds=eligibleStudents().map(s=>s.id);for(const sid of lesson.studentIds)lesson.objectiveIds[sid]=defaultLessonObjective(sid,lesson.domain)?.id;cohort=lesson.studentIds.slice();groups={a:[],b:[]};return render()}
 if(a==='studio-tab'){preserveLessonInputs();studioTab=value;return render()}
 if(a==='studio-step'){preserveLessonInputs();studioStep=+value;return render()}
 if(a==='save-draft'){state.lesson=structuredClone(lesson);if(saveVariationDraft())toast('Draft saved.');return}
 if(a==='open-draft'){const saved=state.drafts.find(d=>d.id===id);if(!saved)return toast('Draft not found.');lesson=structuredClone(saved);lesson.studentIds ||= [];lesson.objectiveIds ||= {};lesson.withVariations=true;studioTab='draft';studioStep=lesson.studentIds.length?2:1;groups={a:[],b:[]};cohort=lesson.studentIds.slice();return navigate('studio')}
 if(a==='edit-variation')return openModal(`Edit version ${value.toUpperCase()}`,'',`<form id="variation-form"><input type="hidden" name="version" value="${value}"><div class="field"><label for="version-name">Version name</label><input id="version-name" name="name" required maxlength="80" value="${esc(lesson[value])}"></div><div class="field"><label for="version-directions">Student directions</label><textarea id="version-directions" name="directions" required maxlength="3000" rows="8">${esc(lesson['directions'+value.toUpperCase()])}</textarea></div><div class="modal-foot">${btn('Cancel','close')}<button class="btn primary" type="submit">Save changes</button></div></form>`);
 if(a==='preview-worksheet')return openModal(`Assignment · Version ${value.toUpperCase()}`,lesson[value],worksheet(value,true)+`<div class="modal-foot"><span class="tiny muted">Review before use.</span>${btn(icon('print')+'Print assignment','print','primary')}</div>`,{wide:true,printable:true});
 if(a==='print')return window.print();
 if(a==='randomize'){cohort=(lesson.studentIds||[]).slice();if(cohort.length<2)return toast('Choose at least two students in step 1.');groups=shuffleStudents(cohort);document.getElementById('groups-panel').innerHTML=groupPanels();el.innerHTML=icon('shuffle')+'Randomize again';return toast('Groups assigned.')}
 if(a==='move-group'){groups[value]=groups[value].filter(s=>s!==id);groups[value==='a'?'b':'a'].push(id);document.getElementById('groups-panel').innerHTML=groupPanels();return}
 if(a==='back-comparisons'){studioTab='comparisons';return navigate('studio')}
 if(a==='reset-confirm')return openModal('Reset the prototype?','',`<p class="small muted">This clears added students, plans, notes, progress, and drafts in this browser.</p><div class="modal-foot">${btn('Cancel','close')}${btn('Reset demo','reset','primary')}</div>`);
 if(a==='reset'){clearEvidenceFiles();students.splice(SEED_STUDENT_COUNT);state=initialState();initializeModel();activeGoalIds={};activeObjectiveIds={};initializeTrials();initializeGuidance();persist();lesson=null;studioStep=1;studioTab='draft';studentTab='overview';activeFilter='all';searchText='';closeModal();navigate('class');toast('Demo reset.')}
});
document.addEventListener('input',e=>{
 if(handleAssignmentInput(e))return;
 if(e.target.id==='student-search'){searchText=e.target.value;document.getElementById('roster-body').innerHTML=rosterRows();document.getElementById('roster-count').textContent=`${filteredStudents().length} of ${students.length} students`}
 if(['log-correct','log-attempts'].includes(e.target.id)){const raw=document.getElementById('log-correct').value,correct=+raw,total=+document.getElementById('log-attempts').value;document.getElementById('score-preview').textContent=raw!==''&&total>0&&correct>=0&&correct<=total?`${Math.round(correct/total*100)}% independent accuracy`:'Enter the number of independent correct answers.'}
});
document.addEventListener('change',e=>{
 if(handleProgressChange(e.target))return;
 if(handleAssignmentChange(e.target))return;
 if(e.target.id==='progress-goal'){const id=e.target.dataset.student;activeGoalIds[id]=e.target.value;delete activeObjectiveIds[id];render()}
 if(e.target.id==='progress-objective'){activeObjectiveIds[e.target.dataset.student]=e.target.value;render()}
 if(e.target.id==='notes-source'){notesSource=e.target.value;render()}
 if(['frequency','plan-start','review-date'].includes(e.target.id))updateTrialScheduleHint();
});
function formError(id,text){document.getElementById(id).innerHTML=`<div class="error" role="alert">${esc(text)}</div>`}
function validObjective(d,g){return d.skill?.trim()&&d.condition?.trim()&&+d.target>0&&+d.target<=100&&Number.isInteger(+d.checks)&&+d.checks>0&&+d.checks<=10&&d.deadline>=TODAY&&d.deadline<=g.deadline}
document.addEventListener('submit',e=>{const form=e.target;if(!['student-form','goal-form','objective-form','measurement-form','lesson-form','assignment-draft-form','context-form','variation-form','comparison-form','log-form','class-scores-form','trial-dates-form','trial-review-form'].includes(form.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(form));
 if(handleTrialSubmit(form,d))return;
 if(form.id==='student-form'){const name=d.name.trim(),grade=+d.grade;if(!name||!Number.isInteger(grade)||grade<0||grade>12)return formError('student-error','Enter a name and grade.');const s={id:uid('student'),name,grade,initials:name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(),color:'sage',domain:'reading',score:null,status:'evidence',last:'No records',points:[],isNew:true};students.push(s);state.addedStudents.push(s);state.goalPlans[s.id]=[];persist();closeModal();studentTab='plan';navigate('student/'+s.id);toast('Student added.');}
 if(form.id==='goal-form'){if(!d.title.trim()||!domainNames[d.domain]||d.deadline<datePlus(21))return formError('goal-error','Enter a goal and a date at least three weeks ahead.');const previous=findGoal(d.student,d.goalId);if(previous){const changed=previous.title!==d.title.trim()||previous.deadline!==d.deadline||previous.domain!==d.domain;Object.assign(previous,{title:d.title.trim(),deadline:d.deadline,domain:d.domain});if(previous.measurement.review>d.deadline)previous.measurement.review=d.deadline;if(changed)for(const o of previous.objectives){o.status='draft';if(o.deadline>d.deadline)o.deadline=d.deadline;}activeGoalIds[d.student]=previous.id;}else{if(!goalPlansFor(d.student).length)getStudent(d.student).domain=d.domain;const g={id:uid('goal'),title:d.title.trim(),domain:d.domain,deadline:d.deadline,measurement:{method:defaultMeasures[d.domain],frequency:'2',review:datePlus(14)}};g.objectives=draftObjectives(getStudent(d.student),g);state.goalPlans[d.student] ||= [];state.goalPlans[d.student].push(g);activeGoalIds[d.student]=g.id;}persist();closeModal();studentTab='plan';navigate('student/'+d.student);toast(previous?'Goal saved. Review objectives.':'SMART objective drafts ready for review.');}
 if(form.id==='objective-form'){const g=findGoal(d.student,d.goalId);if(!g||!validObjective(d,g))return formError('objective-error','Check the skill, target, support, and date within the goal period.');const old=g.objectives.find(o=>o.id===d.objectiveId);const fields={skill:d.skill.trim(),condition:d.condition.trim(),target:+d.target,checks:+d.checks,deadline:d.deadline,status:'draft'};if(old)Object.assign(old,fields);else g.objectives.push({id:uid('objective'),...fields,sample:false});persist();closeModal();render();toast('Objective saved for approval.');}
 if(form.id==='measurement-form'){const g=findGoal(d.student,d.goalId);if(!g||!d.method.trim()||+d.frequency<1||+d.frequency>5||d.review<TODAY||d.review>g.deadline)return formError('measurement-error','Check the measure, frequency, and review date.');g.measurement={method:d.method.trim(),frequency:d.frequency,review:d.review};persist();closeModal();render();toast('Measurement plan saved.');}
 if(form.id==='lesson-form'||form.id==='assignment-draft-form')return submitAssignmentSetup(d,form);
 if(form.id==='variation-form'){lesson[d.version]=d.name.trim();lesson['directions'+d.version.toUpperCase()]=d.directions.trim();state.lesson=structuredClone(lesson);if(state.drafts.some(x=>x.id===lesson.id)){if(!saveVariationDraft())return;}else if(!persist())return;closeModal();render();toast('Assignment updated.')}
 if(form.id==='context-form'){if(!d.author.trim()||!d.text.trim()||!d.dateISO)return;state.contexts.unshift({...d,author:d.author.trim(),text:d.text.trim(),id:uid('note'),date:formatDate(d.dateISO),initials:d.author.trim().split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase(),color:'sage'});refreshGuidance(getStudent(d.student));persist();closeModal();render();toast('Note added. Guidance updated.')}
 if(form.id==='comparison-form'){
  if(!groups.a.length||!groups.b.length)return formError('comparison-error','Randomize the selected students into two groups.');
  if(!d.start||d.start<TODAY||d.review<=d.start||![2,3].includes(+d.frequency))return formError('comparison-error','Choose a start date, a later review date, and 2 or 3 checks per week.');
  const ids=[...groups.a,...groups.b],selected=lesson.studentIds||[];if(new Set(ids).size!==ids.length||ids.length!==selected.length||ids.some(id=>!selected.includes(id)||!eligibleStudents().some(s=>s.id===id)))return formError('comparison-error','Groups must include exactly the students selected in step 1.');
  if(!saveVariationDraft())return formError('comparison-error','Could not save the lessons. Free some browser storage and try again.');
  const objectiveIds=structuredClone(lesson.objectiveIds);const comparison={id:uid('comparison'),title:lesson.title,lesson:structuredClone(lesson),groups:structuredClone(groups),objectiveIds,measure:d.measure,frequency:+d.frequency,start:d.start,activatedAt:null,decisions:{},review:d.review,baseline:d.baseline,baselines:d.baseline==='recent'?Object.fromEntries(ids.map(id=>[id,scoreForObjective(getStudent(id),lessonObjectiveOptions(id,lesson.domain).find(o=>o.id===objectiveIds[id]))])):{},started:TODAY};state.comparisons.unshift(comparison);state.lesson=structuredClone(lesson);persist();navigate('comparison/'+comparison.id);toast('Teaching plan ready.');
 }
 if(form.id==='log-form')return saveProgressRecord(d,form);

});
overlay.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('keydown',e=>{if(!overlay.innerHTML)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...overlay.querySelectorAll('button,a[href],input,select,textarea,[contenteditable="true"],[tabindex="0"]')].filter(el=>!el.disabled&&el.type!=='hidden'&&!el.hidden&&!el.closest?.('[hidden]'));const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
